ALTER TABLE public.habitos_jornada ADD COLUMN missao_principal text, ADD COLUMN missao_secundaria text;
COMMENT ON COLUMN public.habitos_jornada.missao_principal IS 'Ação principal da missão, exibida com destaque.';
COMMENT ON COLUMN public.habitos_jornada.missao_secundaria IS 'Orientações complementares de observação e relato ao Neo.';
UPDATE public.habitos_jornada AS h SET missao_principal=v.principal, missao_secundaria=v.secundaria FROM (VALUES
('b2f599e9-d8ae-43de-abb7-263667fb4a10'::uuid, 'Quando a vontade surgir, observe o gatilho, seu corpo e seus pensamentos, sem agir imediatamente. Diga: “Estou com vontade de fumar” e perceba como a vontade muda com o tempo. Repita por 3 dias.', 'Depois, conte ao Neo o que descobriu sobre a sua vontade de fumar.'),
('9a976f27-d52a-4315-a6ef-90e0cef1f375'::uuid, 'Nos próximos dias, observe o que acontece antes da vontade de fumar: onde você está, o que faz e como se sente.', 'Conte ao Neo os padrões que percebeu.'),
('57a9b3fc-c2ba-4181-a628-5071254474d3'::uuid, 'Faça algo que costuma adiar e que pode trazer bem-estar: caminhar, organizar um espaço ou preparar uma refeição.', 'Observe como se sente antes e depois e compartilhe com o Neo.'),
('ac0ce7f1-6a5d-4d1e-b081-ab7c0eff8688'::uuid, 'Em um momento em que costumava fumar em casa, faça uma pausa de 5 minutos sem cigarro. Sente-se, alongue-se ou tome um copo de água ou café.', 'Observe como se sente e conte ao Neo.'),
('8dd9abf6-aeab-4fba-a39e-c4d3715cb194'::uuid, 'Escolha um cuidado simples por dia: caminhar, beber água, dormir melhor, comer algo nutritivo ou se movimentar.', 'Observe como você se sente e conte ao Neo qual escolha fez.'),
('d39a7cb6-7d2f-4c60-aabb-26447e819c16'::uuid, 'Nos próximos dias, repare nos momentos em que antes você fumava e agora já se acostumou a ficar sem cigarro, mesmo em situações pequenas.', 'Observe o que essas escolhas dizem sobre você e compartilhe com o Neo.'),
('7b639a41-2376-4f38-b525-e042dfeca233'::uuid, 'Antes do próximo encontro com amigos, escolha uma estratégia para lidar com o pensamento automático de fumar, como ter sempre água por perto.', 'Depois, conte ao Neo o que funcionou.'),
('c73c8155-ca0a-4bc6-af6f-2c9d478f6e8d'::uuid, 'Se encontrar alguém fumando, observe sua vontade e escolha como se cuidar: afastar-se, mudar de assunto ou respirar. Diga: “Que bom que não sou mais essa pessoa, sou mais feliz agora.”', 'Depois, conte ao Neo como foi.'),
('53a74c4e-7ab6-4621-9571-dc4a749ab3cc'::uuid, 'Em uma refeição, coma sem pressa nem culpa. Preste atenção ao sabor, à textura, à temperatura e ao momento em que sente saciedade.', 'Conte ao Neo como se sentiu após essas refeições.'),
('4352b797-c08d-481f-aca6-8695dbd9b5ae'::uuid, 'Escolha um movimento que você realmente goste e que seja possível hoje: caminhar, dançar ou alongar-se por alguns minutos.', 'Observe sua energia e seu humor antes e depois. Conte ao Neo como foi.'),
('d10f393f-5dfa-447c-a963-05e030e6edc5'::uuid, 'Durante 3 dias, escolha um cigarro por dia para fumar sem distrações. Antes e durante, observe a vontade, o cheiro, o gosto e as sensações.', 'Compare o prazer esperado com o que realmente sentiu e conte ao Neo como foi essa experiência.'),
('8f09dc88-67f4-463b-9002-153b2398a971'::uuid, 'Quando sentir vontade de fumar por ansiedade ou estresse, faça 10 respirações lentas antes de decidir.', 'Observe o corpo, a ansiedade e a vontade. Conte ao Neo se conseguiu se acalmar, mesmo se acabou fumando depois das respirações.'),
('0529c333-bf93-4ac8-a29b-1281f2e96669'::uuid, 'Faça uma tarefa que costuma adiar, como caminhar, arrumar a casa ou resolver algo simples.', 'Observe sua disposição antes e depois e reflita sobre como é bom ter energia para realizar as coisas na vida. Conte ao Neo como foi.'),
('45b422bb-885c-4682-b871-58fbd8f0ed04'::uuid, 'Escolha uma tarefa importante por dia e tente realizá-la por 10 minutos antes de fumar.', 'Observe a concentração, as distrações e o que ajudou você a começar. Conte ao Neo como foi começar sem fumar.'),
('d30e2aa3-b449-4803-8c3e-199df6863bb3'::uuid, 'Uma vez por dia, faça uma pausa de 5 minutos sem cigarro. Caminhe, alongue-se ou respire tranquilamente. Repita por 3 dias.', 'Observe como estava antes e depois e conte ao Neo.'),
('ff9b3e48-8fc7-4727-97b4-9a4993f2c92d'::uuid, 'Escolha uma situação em que costuma fumar, como ver TV ou falar ao telefone, e tente vivê-la sem cigarro. Repita 3 vezes.', 'Observe quando a vontade surge e o que acontece depois. Conte ao Neo como foi.'),
('cd782913-4e48-4058-b190-ffc031a517c4'::uuid, 'Quando sentir tédio, fique 5 minutos sem fumar e sem pegar o celular. Repita 3 vezes.', 'Observe pensamentos, sensações e vontades e conte ao Neo o que percebeu.'),
('2041764b-89fa-4d11-8dce-1468e06cea4b'::uuid, 'Durante 3 dias, escolha uma refeição por dia para fazer sem fumar antes, durante ou depois.', 'Perceba o gosto da comida sem estar misturado com o gosto do cigarro. Observe a vontade e conte ao Neo.'),
('15f46a7f-8c74-42f6-a3a3-42058200d4d7'::uuid, 'Durante 3 dias, escolha um café por dia para tomar sem fumar antes, durante ou depois. Espere pelo menos 1 hora depois do café para fumar um cigarro.', 'Observe o sabor, os pensamentos e a vontade de fumar. Conte ao Neo como foi essa experiência.'),
('0d117ace-7d9a-4389-bb8e-f922be25b213'::uuid, 'Na próxima situação social, espere 15 minutos antes de fumar. Converse com alguém ou observe quem não fuma.', 'Perceba se a vontade muda e se você consegue aproveitar o momento. Depois, conte ao Neo.'),
('fbcda2ab-fb66-473e-b756-b1fb571a9d43'::uuid, 'Nos próximos 3 dias, deixe o primeiro cigarro para depois do café da manhã.', 'Observe a vontade ao acordar e como ela muda enquanto você segue sua rotina. Depois, conte ao Neo como foi.')
) AS v(id, principal, secundaria) WHERE h.id=v.id;